#!/usr/bin/env node
/**
 * Minimal self-hosted Expo Updates server.
 *
 * Implements the subset of the Expo Updates protocol (v1) that the official
 * `expo-updates` client needs:
 *
 *   GET /manifest           -> the update manifest (JSON)
 *   GET /assets/*           -> the JS bundle and static assets
 *   GET /headers.json       -> expo-server-defined-headers for the client
 *
 * The manifest is generated by `publish-mobile-update.mjs`, which runs
 * `expo export` and writes `manifest.json` next to the exported files.
 *
 * Run it:
 *   node scripts/updates-server.mjs --dir mobile/dist/updates --port 4001
 *
 * Point the app at it with the "Update server" field on the mobile login
 * screen, or set `expo.updates.url` in app.json before building.
 */
import { createServer } from "node:http";
import { readFile, stat } from "node:fs/promises";
import { join, extname, resolve, normalize } from "node:path";

const args = process.argv.slice(2);
function arg(name, fallback) {
  const i = args.indexOf(`--${name}`);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
}

const root = resolve(arg("dir", "mobile/dist/updates"));
const port = Number(arg("port", "4001"));
const host = arg("host", "0.0.0.0");

const MIME = {
  ".js": "application/javascript",
  ".json": "application/json",
  ".css": "text/css",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".gif": "image/gif",
  ".svg": "image/svg+xml",
  ".ttf": "font/ttf",
  ".otf": "font/otf",
  ".woff": "font/woff",
  ".woff2": "font/woff2",
  ".map": "application/json",
  ".hbc": "application/javascript",
};

function send(res, status, body, headers = {}) {
  res.writeHead(status, { "Cache-Control": "no-store", ...headers });
  res.end(body);
}

async function serveFile(res, filePath) {
  try {
    const data = await readFile(filePath);
    const type = MIME[extname(filePath).toLowerCase()] ?? "application/octet-stream";
    send(res, 200, data, { "Content-Type": type });
  } catch {
    send(res, 404, JSON.stringify({ error: "not found" }), { "Content-Type": MIME[".json"] });
  }
}

const server = createServer(async (req, res) => {
  const url = new URL(req.url ?? "/", `http://${req.headers.host ?? "localhost"}`);
  const pathname = decodeURIComponent(url.pathname);

  // The Expo client sends these headers; echo the ones we care about.
  const runtimeVersion = req.headers["expo-runtime-version"] ?? "";
  const platform = req.headers["expo-platform"] ?? "";

  if (pathname === "/manifest" || pathname === "/" || pathname === "/updates") {
    let manifest;
    try {
      manifest = JSON.parse(await readFile(join(root, "manifest.json"), "utf8"));
    } catch {
      send(res, 404, JSON.stringify({ error: "no update published" }), { "Content-Type": MIME[".json"] });
      return;
    }
    // Only serve the update if it matches the runtime the client wants.
    if (runtimeVersion && manifest.runtimeVersion && manifest.runtimeVersion !== runtimeVersion) {
      send(res, 404, JSON.stringify({ error: "no update for this runtime version" }), {
        "Content-Type": MIME[".json"],
      });
      return;
    }
    // Rewrite relative asset URLs to absolute ones pointing at this server.
    const base = `http://${req.headers.host ?? `${host}:${port}`}`;
    const body = {
      ...manifest,
      launchAsset: { ...manifest.launchAsset, url: absolute(base, manifest.launchAsset.url) },
      assets: (manifest.assets ?? []).map((a) => ({ ...a, url: absolute(base, a.url) })),
    };
    send(res, 200, JSON.stringify(body), {
      "Content-Type": "application/expo+json",
      "expo-protocol-version": "1",
      "expo-sfv-version": "0",
      "cache-control": "private, max-age=0",
      "expo-server-defined-headers": JSON.stringify({
        "expo-channel-name": "production",
        "expo-platform": platform || "android",
      }),
    });
    return;
  }

  if (pathname === "/headers.json") {
    send(res, 200, JSON.stringify({ "expo-channel-name": "production" }), {
      "Content-Type": MIME[".json"],
    });
    return;
  }

  // Static assets.
  const rel = normalize(pathname).replace(/^(\.\.[/\\])+/, "").replace(/^[/\\]+/, "");
  const filePath = join(root, rel);
  if (!filePath.startsWith(root)) {
    send(res, 403, JSON.stringify({ error: "forbidden" }), { "Content-Type": MIME[".json"] });
    return;
  }
  try {
    const s = await stat(filePath);
    if (!s.isFile()) throw new Error("not a file");
  } catch {
    send(res, 404, JSON.stringify({ error: "not found" }), { "Content-Type": MIME[".json"] });
    return;
  }
  await serveFile(res, filePath);
});

function absolute(base, u) {
  if (!u) return u;
  if (/^https?:\/\//i.test(u)) return u;
  return `${base}/${u.replace(/^\/+/, "")}`;
}

server.listen(port, host, () => {
  console.log(`Expo updates server on http://${host}:${port}`);
  console.log(`  manifest: http://${host}:${port}/manifest`);
  console.log(`  serving:  ${root}`);
});
